#include "udf.hpp"

/*
 * User-defined functions for turbulent pipe flow at Re_tau = 550
 * Polynomial order 7, 32,000 elements
 * Initial condition: laminar parabolic profile with small divergence-free perturbation
 * Body force (pressure gradient) specified in .par via bodyForce = 0 0 2.0
 */

void UDF_Setup(nrs_t *nrs) {
  // No additional setup required; body force handled by .par
  // Statistics collection configured in .par [STATISTICS] block
}

void UDF_LoadForce(nrs_t *nrs, dfloat time, int step) {
  // Body force is constant and defined in .par [FLUID] bodyForce = 0 0 2.0
  // This function is called each step but no action needed here
}

void UDF_ExecuteStep(nrs_t *nrs, dfloat time, int step) {
  // Per-step operations (if any)
  // Statistics are automatically collected per [STATISTICS] block in .par
}

void UDF_InitialConditions(nrs_t *nrs, dfloat time, int step) {
  // Initialize velocity field with laminar profile + perturbation
  // Laminar solution for pipe: u_z = (1/(4*nu)) * (-dp/dz) * (R^2 - r^2)
  // With -dp/dz = 2.0, nu = 1/550, R = 1.0:
  // u_z = (550/4) * 2.0 * (1 - r^2) = 275.0 * (1 - r^2)
  // Add small divergence-free perturbation to trigger transition

  auto mesh = nrs->mesh;
  const int n = mesh->Nlocal;
  auto U = nrs->U;  // velocity components: [Ux, Uy, Uz] interleaved

  // Embedded OKL kernel for initial condition
  static occa::kernel initKernel = nullptr;
  if (!initKernel) {
    const char* kernelSource = R"(
      @kernel void initVelocity(
        const int n,
        const dfloat *x, const dfloat *y, const dfloat *z,
        dfloat *U
      ) {
        for (int i = 0; i < n; ++i; @tile(256, @outer, @inner)) {
          const dfloat r2 = x[i]*x[i] + y[i]*y[i];
          const dfloat r = sqrt(r2);
          // Laminar parabolic profile: u_z = 275*(1-r^2)
          const dfloat uLaminar = 275.0 * (1.0 - r2);
          // Small random perturbation (using hash of coordinates for reproducibility)
          const dfloat eps = 1e-3;
          const int seed = (int)(x[i]*1000) ^ (int)(y[i]*1000) ^ (int)(z[i]*1000);
          const dfloat randVal = (sin(seed * 12.9898) * 43758.5453);
          const dfloat perturb = eps * (randVal - floor(randVal)) * 2.0 - 1.0;
          // Velocity components: x, y, z (axial)
          U[3*i + 0] = -y[i] * perturb;  // Azimuthal perturbation
          U[3*i + 1] =  x[i] * perturb;  // Divergence-free in cross-section
          U[3*i + 2] = uLaminar;         // Axial laminar profile
        }
      }
    )";
    initKernel = nrs->device->buildKernelFromString(
      kernelSource, "initVelocity", nrs->kernelInfo
    );
  }

  initKernel(n, mesh->x, mesh->y, mesh->z, U);
}
```
**Why needed:** Provides the initial velocity field (laminar profile at the target pressure gradient plus a small divergence-free perturbation to initiate transition to turbulence). The body force and statistics are driven from the .par, so UDF_LoadForce and UDF_ExecuteStep are no-ops; UDF_Setup is present for completeness.

